CREATE INDEX "IX_funciones_sala_id_experiencia_id" ON cine.funciones (sala_id, experiencia_id);


CREATE UNIQUE INDEX "IX_funciones_sala_id_inicio_utc" ON cine.funciones (sala_id, inicio_utc);


CREATE UNIQUE INDEX "IX_generos_nombre" ON cine.generos (nombre);


CREATE INDEX "IX_pedido_lineas_combo_id" ON cine.pedido_lineas (combo_id);


CREATE INDEX "IX_pedido_lineas_pedido_id" ON cine.pedido_lineas (pedido_id);


CREATE INDEX "IX_pedidos_entregado_por_id" ON cine.pedidos (entregado_por_id);


CREATE INDEX "IX_pedidos_estado_creado_utc" ON cine.pedidos (estado, creado_utc);


CREATE UNIQUE INDEX "IX_pedidos_numero" ON cine.pedidos (numero);


