-- Fichas e imágenes verificadas en TMDB. Fechas de exhibición relativas al BAT.
-- Jumanji y Beyond the Spider-Verse usan una duración operativa provisional, porque TMDB aún no la informa.
INSERT INTO cine.peliculas (id, tmdb_id, titulo, sinopsis, poster, fondo, trailer_url, foco_poster, foco_fondo, duracion, limpieza, estreno, distribuidora_id, idiomas_json, preventa, publicada, creado_utc) VALUES
(1423191, 1423191, 'Resident Evil: Noche cero', 'Película basada en la saga de videojuegos de Capcom del mismo nombre. En una reinvención totalmente nueva, el mensajero médico Bryan se ve inmerso en una carrera de acción sin descanso por la supervivencia, mientras el caos se desata a su alrededor.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1423191-poster-cfdcd0a285ff.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1423191-fondo-26c124cd7c1f.webp', 'https://www.youtube.com/watch?v=d6oszs7f5aI', 50, 40, 95, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -45), 8, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '70 days')),
(1400837, 1400837, 'Madre siniestra', 'Bela, una niña de 8 años que vive en un hogar con problemas matrimoniales, enfrenta a una entidad siniestra que sale de su armario. La presencia, a quien llama "Otra mamá", se vuelve cada vez más amenazante para ella y su familia.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1400837-poster-e4ac360d8235.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1400837-fondo-1e148dcfc5eb.webp', 'https://www.youtube.com/watch?v=ocV7K_B67lQ', 50, 40, 93, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -46), 2, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '71 days')),
(1078605, 1078605, 'Weapons: La hora de la desaparición', 'Cuando todos los alumnos de una misma clase, salvo uno, desaparecen misteriosamente la misma noche y exactamente a la misma hora, la pequeña ciudad donde viven se pregunta quién o qué está detrás de su desaparición.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1078605-poster-c36d3c474504.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1078605-fondo-0d5842d62737.webp', 'https://www.youtube.com/watch?v=lZyASo3yaTA', 50, 40, 129, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -47), 4, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '72 days')),
(696506, 696506, 'Mickey 17', 'Mickey 17, un miembro de la tripulación ''expendable'' (prescindible) enviado a un planeta helado para colonizarlo, se niega a dejar que su clon de reemplazo, Mickey 18, tome su lugar... Adaptación del libro original de Edward Ashton.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/696506-poster-678f40b80356.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/696506-fondo-959e7b8cadd4.webp', 'https://www.youtube.com/watch?v=vzvAieKSWqA', 50, 40, 137, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -48), 4, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '73 days')),
(986056, 986056, 'Thunderbolts*', 'Un grupo de supervillanos poco convencional es reclutado para hacer misiones para el gobierno: Yelena Belova, Bucky Barnes, Red Guardian, Ghost, Taskmaster y John Walker. Después de verse atrapados en una trampa mortal urdida por Valentina Allegra de Fontaine, estos marginados deben embarcarse en una peligrosa misión que les obligará a enfrentarse a los recovecos más oscuros de su pasado.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/986056-poster-e20a5b4054eb.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/986056-fondo-911e460e158d.webp', 'https://www.youtube.com/watch?v=QCbzHZ1Q2lw', 50, 40, 127, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -49), 1, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '74 days')),
(936075, 936075, 'Michael', 'El viaje de Michael Jackson más allá de la música, desde el descubrimiento de su extraordinario talento como líder de los Jackson Five hasta convertirse en una visionaria estrella cuya ambición creativa despertó un incansable afán por consagrarse como el mayor icono de la industria del entretenimiento.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/936075-poster-b3a1684be906.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/936075-fondo-e99d6ec1949d.webp', 'https://www.youtube.com/watch?v=o1HQSh6zZ8s', 50, 40, 128, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -50), 15, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '75 days')),
(1153576, 1153576, 'Street Fighter', 'En 1993, los distanciados luchadores callejeros Ryu y Ken Masters se ven arrastrados de nuevo al combate cuando la misteriosa Chun-Li los recluta para el próximo Torneo World Warrior: un enfrentamiento brutal de puños, destino y furia. Sin embargo, tras esta gran batalla se esconde una conspiración mortal que los obliga a enfrentarse tanto entre sí como a los demonios de su pasado. Y si no lo logran... ¡será el fin de la partida!', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1153576-poster-59e2ccf84a0f.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1153576-fondo-a973c5c254c5.webp', 'https://www.youtube.com/watch?v=-MJAfIMUQ5s', 50, 40, 125, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -51), 9, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '76 days')),
(1255833, 1255833, 'Whalefall', 'Tras la muerte de su padre, Jay Gardiner se sumerge en la costa central de California en busca de sus restos, pero es tragado por una ballena. Atrapado en su interior con solo una hora de oxígeno restante, Jay se da cuenta de que las lecciones que su padre le enseñó pueden ser la clave para escapar.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1255833-poster-914ce3cc2fe0.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1255833-fondo-3e4584711eb0.webp', 'https://www.youtube.com/watch?v=5webTf9wplE', 50, 40, 98, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -52), 12, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '77 days')),
(969681, 969681, 'Spider-Man: Brand New Day', 'Han pasado cuatro años desde los acontecimientos de No Way Home, y Peter Parker ahora es un adulto que vive completamente solo, ha desaparecido voluntariamente de las vidas y recuerdos de quienes ama. Combatiendo el crimen en una Nueva York que ya no conoce su nombre, se ha dedicado por completo a proteger su ciudad—un Spider-Man a tiempo completo—, pero a medida que aumentan las exigencias sobre él, la presión desencadena una evolución física que amenaza su existencia, al mismo tiempo que un extraño nuevo patrón de crímenes da lugar a una de las amenazas más poderosas a las que se ha enfrentado.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/969681-poster-82cb189d2475.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/969681-fondo-cf5af805a95e.webp', 'https://www.youtube.com/watch?v=o8EccyRIwQQ', 50, 40, 145, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -53), 8, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '78 days')),
(1368337, 1368337, 'La odisea', 'Tras la caída de Troya, el legendario rey de Ítaca, Odiseo a.k.a. Ulises, emprende un largo y peligroso viaje para regresar junto a su esposa Penélope y su hijo Telémaco. En el camino deberá enfrentarse a criaturas mitológicas, dioses caprichosos y pruebas que pondrán a prueba su ingenio, su resistencia y su humanidad. Mientras tanto, en Ítaca, el futuro de su reino pende de un hilo ante la creciente amenaza de quienes creen que jamás volverá.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1368337-poster-4f4b079b34b3.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1368337-fondo-aa30232de55c.webp', 'https://www.youtube.com/watch?v=X9nUrOnHlz0', 50, 40, 173, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -54), 2, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '79 days')),
(1083381, 1083381, 'Backrooms', 'Una extraña puerta aparece en el sótano de una tienda de muebles. Cuando el paciente de una terapeuta desaparece en una dimensión más allá de la realidad, ella deberá adentrarse en lo desconocido para intentar rescatarlo.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1083381-poster-b98419459a52.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1083381-fondo-2d8811e99032.webp', 'https://www.youtube.com/watch?v=9EYRSmbsqzY', 50, 40, 111, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -55), 6, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '80 days')),
(687163, 687163, 'Proyecto salvación', 'El profesor de ciencias Ryland Grace se despierta en una nave espacial a años luz de casa sin recordar quién es ni cómo ha llegado hasta allí. A medida que recupera la memoria, empieza a descubrir su misión: resolver el enigma de la misteriosa sustancia que provoca la extinción del sol. Deberá recurrir a sus conocimientos científicos y a sus ideas poco ortodoxas para salvar todo lo que hay en la Tierra de la extinción... pero una amistad inesperada significa que quizá no tenga que hacerlo solo.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/687163-poster-f1625f8e4fae.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/687163-fondo-cf29fd2fca46.webp', 'https://www.youtube.com/watch?v=in-lUuKi0eE', 50, 40, 156, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -56), 7, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '81 days')),
(1212763, 1212763, 'Posesión infernal: En llamas', 'Tras la muerte de su marido, una mujer busca consuelo junto a la familia de este en su aislada casa familiar. Pero, cuando uno a uno comienzan a convertirse en seres poseídos, el encuentro acaba convirtiéndose en una reunión familiar salida del infierno. Entonces descubre que los votos que hizo en vida siguen vigentes incluso después de la muerte.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1212763-poster-704f90e41e5c.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1212763-fondo-b76aee4c4efa.webp', 'https://www.youtube.com/watch?v=xs9rmpoEzNs', 50, 40, 110, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -57), 4, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '82 days')),
(1291595, 1291595, 'Insidious: Fuera del más allá', 'La saga de terror vuelve a sus raíces sobrenaturales. Una nueva protagonista se enfrenta a misteriosas apariciones que van mucho más allá de los fenómenos de embrujamiento clásicos. El mal encuentra nuevos caminos en la realidad. Un trío de acechadores se infiltra en un tranquilo suburbio obligando a una nueva familia a entrar en el plano astral, donde descubren una aterradora verdad: el Más Allá está sangrando en el mundo real', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1291595-poster-562a9f984661.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1291595-fondo-323566f89ffc.webp', 'https://www.youtube.com/watch?v=gXjurDkYnEM', 50, 40, 106, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -58), 8, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '83 days')),
(1159559, 1159559, 'Scream 7', 'Cuando un nuevo asesino Ghostface aparece en el tranquilo pueblo donde Sidney Prescott ha construido una nueva vida, sus peores miedos se hacen realidad cuando su hija se convierte en el siguiente objetivo. Decidida a proteger a su familia, Sidney debe enfrentarse a los horrores de su pasado para poner fin a la masacre de una vez por todas.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1159559-poster-829e8d0da3f4.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1159559-fondo-dcccd7258f75.webp', 'https://www.youtube.com/watch?v=bK-Sam8baFU', 50, 40, 114, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -59), 9, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '84 days')),
(1081003, 1081003, 'Supergirl', 'Kara Zor-El es una heroína errabunda que decide aliarse a regañadientes con un compañero improbable para comenzar un viaje épico e interestelar de venganza y justicia, en el cual deberá decidir si su fuerza sirve para destruir o para proteger.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1081003-poster-5e334d0f235c.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1081003-fondo-86453b476c52.webp', 'https://www.youtube.com/watch?v=9rZLuGQrrjs', 50, 40, 108, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -60), 4, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '85 days')),
(1003596, 1003596, 'Avengers: Doomsday', 'Quinta entrega de la saga ''Vengadores'' incluida en el Universo Cinematográfico Marvel (UCM). Sinopsis desconocido.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1003596-poster-33828f1d5c69.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1003596-fondo-8b9e6ec27900.webp', 'https://www.youtube.com/watch?v=gcjnEYJ4OB8', 50, 40, 165, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 35), 1, '["Español","Subtitulada"]', TRUE, TRUE, (CURRENT_TIMESTAMP - interval '86 days')),
(1300968, 1300968, 'Los juegos del hambre: Amanecer en la cosecha', 'Explora Panem 24 años antes de la saga de Katniss, comenzando en la mañana de la siega de los 50º Juegos del Hambre, donde participa un joven Haymitch Abernathy.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1300968-poster-f0e78c53c9ff.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1300968-fondo-ccb3231eac2f.webp', 'https://www.youtube.com/watch?v=71wxo7pAKVE', 50, 40, 150, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 42), 15, '["Español","Subtitulada"]', TRUE, TRUE, (CURRENT_TIMESTAMP - interval '87 days')),
(1170608, 1170608, 'Dune: Parte tres', 'Paul Atreides, ahora Emperador Muad''Dib, se desenvuelve en su inmenso poder mientras lucha contra enemigos políticos y una conspiración dentro de su círculo. Mientras la Casa Atreides se enfrenta al colapso, surge el verdadero peligro para la amante de Paul, Chani, y su heredero nonato.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1170608-poster-fa9d05a97789.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1170608-fondo-0fc418e9badd.webp', 'https://www.youtube.com/watch?v=qdfXYN5kMBY', 50, 40, 140, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 49), 4, '["Español","Subtitulada"]', TRUE, TRUE, (CURRENT_TIMESTAMP - interval '88 days')),
(1538497, 1538497, 'Hechizo: Bienvenidos a Hexe', 'Billie, una adolescente impulsiva y poco convencional, desata accidentalmente unos poderes mágicos secretos y sale disparada de los suburbios hacia un reino mágico llamado Hexe, donde la reciben Ms. Quill y Elias Quire. A medida que se desarrolla el viaje de Billie, descubre misterios familiares que podrían cambiar para siempre el mundo mágico de las brujas.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1538497-poster-cbc19b71c61e.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1538497-fondo-7c0bc0aa8ce5.webp', 'https://www.youtube.com/watch?v=UFvfSI8-HGQ', 50, 40, 110, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 56), 1, '["Español","Subtitulada"]', TRUE, TRUE, (CURRENT_TIMESTAMP - interval '89 days')),
(1260649, 1260649, 'Jumanji: Mundo abierto', 'Nuestros héroes ya han logrado escapar de las peligrosas selvas de Jumanji, pero esta vez Jumanji se libera de su consola y desata el caos en nuestro mundo.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1260649-poster-d7401f3bc930.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1260649-fondo-f96495294e18.webp', 'https://www.youtube.com/watch?v=5cbwuO5ZM_w', 50, 40, 120, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 63), 8, '["Español","Subtitulada"]', TRUE, TRUE, (CURRENT_TIMESTAMP - interval '90 days')),
(1421903, 1421903, 'Licantropo', 'Ambientada en la Inglaterra del siglo XIII, Werwulf sigue a un hombre afligido por una maldición que lo transforma en lobo, poniendo en peligro a su familia en una remota zona rural. La lucha por contener a la bestia y la búsqueda de una cura por parte de su esposa se complican con la llegada de un implacable cazador, en una producción cinematográfica hablada por completo en inglés medio.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1421903-poster-19a8bf6966cf.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1421903-fondo-f043de60078f.webp', 'https://www.youtube.com/watch?v=m7oRH0jExvI', 50, 40, 120, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 70), 2, '["Español","Subtitulada"]', TRUE, TRUE, (CURRENT_TIMESTAMP - interval '91 days')),
(1400336, 1400336, 'Ahora los suegros son ellos', 'Henry, hijo de Greg y Pam Focker, se enfrenta al caos familiar cuando decide casarse con una mujer de carácter fuerte que parece ser totalmente incompatible con él.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1400336-poster-b662227f204e.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1400336-fondo-e26693070957.webp', 'https://www.youtube.com/watch?v=j0MROuSV-pA', 50, 40, 105, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 77), 2, '["Español","Subtitulada"]', TRUE, TRUE, (CURRENT_TIMESTAMP - interval '92 days')),
(911916, 911916, 'Spider-Man: Beyond the Spider-Verse', 'La historia continua de Miles Morales y los muchos otros Spider-People de diferentes realidades.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/911916-poster-37225bcc5285.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/911916-fondo-d8cdc1ac0395.webp', '', 50, 40, 140, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 84), 8, '["Español","Subtitulada"]', TRUE, TRUE, (CURRENT_TIMESTAMP - interval '93 days'));

