INSERT INTO cine.estrenos (id, titulo, imagen, genero, fecha, sinopsis, publicado, pelicula_id) VALUES
(1003596, 'Avengers: Doomsday', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1003596-poster-33828f1d5c69.webp', 'Ciencia ficción', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 35), 'Quinta entrega de la saga ''Vengadores'' incluida en el Universo Cinematográfico Marvel (UCM). Sinopsis desconocido.', TRUE, 1003596),
(1300968, 'Los juegos del hambre: Amanecer en la cosecha', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1300968-poster-f0e78c53c9ff.webp', 'Ciencia ficción', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 42), 'Explora Panem 24 años antes de la saga de Katniss, comenzando en la mañana de la siega de los 50º Juegos del Hambre, donde participa un joven Haymitch Abernathy.', TRUE, 1300968),
(1170608, 'Dune: Parte tres', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1170608-poster-fa9d05a97789.webp', 'Ciencia ficción', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 49), 'Paul Atreides, ahora Emperador Muad''Dib, se desenvuelve en su inmenso poder mientras lucha contra enemigos políticos y una conspiración dentro de su círculo. Mientras la Casa Atreides se enfrenta al colapso, surge el verdadero peligro para la amante de Paul, Chani, y su heredero nonato.', TRUE, 1170608),
(1538497, 'Hechizo: Bienvenidos a Hexe', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1538497-poster-cbc19b71c61e.webp', 'Aventura', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 56), 'Billie, una adolescente impulsiva y poco convencional, desata accidentalmente unos poderes mágicos secretos y sale disparada de los suburbios hacia un reino mágico llamado Hexe, donde la reciben Ms. Quill y Elias Quire. A medida que se desarrolla el viaje de Billie, descubre misterios familiares que podrían cambiar para siempre el mundo mágico de las brujas.', TRUE, 1538497),
(1260649, 'Jumanji: Mundo abierto', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1260649-poster-d7401f3bc930.webp', 'Aventura', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 63), 'Nuestros héroes ya han logrado escapar de las peligrosas selvas de Jumanji, pero esta vez Jumanji se libera de su consola y desata el caos en nuestro mundo.', TRUE, 1260649),
(1421903, 'Licantropo', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1421903-poster-19a8bf6966cf.webp', 'Terror', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 70), 'Ambientada en la Inglaterra del siglo XIII, Werwulf sigue a un hombre afligido por una maldición que lo transforma en lobo, poniendo en peligro a su familia en una remota zona rural. La lucha por contener a la bestia y la búsqueda de una cura por parte de su esposa se complican con la llegada de un implacable cazador, en una producción cinematográfica hablada por completo en inglés medio.', TRUE, 1421903),
(1400336, 'Ahora los suegros son ellos', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1400336-poster-b662227f204e.webp', 'Comedia', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 77), 'Henry, hijo de Greg y Pam Focker, se enfrenta al caos familiar cuando decide casarse con una mujer de carácter fuerte que parece ser totalmente incompatible con él.', TRUE, 1400336),
(911916, 'Spider-Man: Beyond the Spider-Verse', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/911916-poster-37225bcc5285.webp', 'Animación', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 84), 'La historia continua de Miles Morales y los muchos otros Spider-People de diferentes realidades.', TRUE, 911916);

INSERT INTO cine.ajustes (clave, valor) VALUES
('banners.automatico', 'false');



-- Histórico de los veintinueve días anteriores: solo funciones que ya terminaron.
-- Hoy conserva la ocupación de demostración y sus pagos del bloque siguiente.
-- Más actividad en fin de semana y por la noche, con variación diaria y por sala.
-- Se reservan dos butacas libres para las compras del cliente de demostración.
WITH clientes AS (
 SELECT u.*,row_number() OVER(ORDER BY u.id)-1 posicion,count(*) OVER() cantidad_clientes
 FROM cine.usuarios u WHERE u.activo AND u.email<>'cliente@cliente.com'
 AND u.fecha_registro_utc <= (((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date-30)::timestamp AT TIME ZONE 'America/La_Paz')
 AND EXISTS(SELECT 1 FROM cine.usuarios_roles ur JOIN cine.roles r ON r.id=ur.role_id WHERE ur.user_id=u.id AND r.name='Cliente')
), candidatas AS (
 SELECT f.*,s.precio,s.descuento,s.tipo_sala_id,d.plano_json,
   (CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date-(f.inicio_utc AT TIME ZONE 'America/La_Paz')::date AS dia,
   extract(hour FROM f.inicio_utc AT TIME ZONE 'America/La_Paz')::int AS hora,
   CASE WHEN extract(isodow FROM f.inicio_utc AT TIME ZONE 'America/La_Paz') IN(5,6,7) THEN 16 ELSE 0 END AS refuerzo
 FROM cine.funciones f JOIN cine.salas s ON s.id=f.sala_id JOIN cine.disenos d ON d.id=s.diseno_id
 WHERE NOT f.preventa AND f.inicio_utc+make_interval(mins=>f.duracion)<=CURRENT_TIMESTAMP
 AND (f.inicio_utc AT TIME ZONE 'America/La_Paz')::date BETWEEN (CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date-29 AND (CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date-1
), asientos AS (
 SELECT c.*,a.asiento,a.posicion,(a.posicion-1)/4 AS grupo
 FROM candidatas c CROSS JOIN LATERAL (
   SELECT asiento,row_number() OVER(ORDER BY regexp_replace(asiento,'[0-9]','','g'),substring(asiento from '[0-9]+')::int) AS posicion
   FROM jsonb_array_elements_text(c.plano_json->'asientos') a(asiento)
 ) a
 WHERE a.posicion <= greatest(0,least(jsonb_array_length(c.plano_json->'asientos')-2,
   8+(c.dia*7)%13+c.sala_id%7+c.refuerzo+CASE WHEN c.hora>=18 THEN 10 ELSE 0 END))
), compras AS (
 SELECT id,sala_id,pelicula_id,experiencia_id,tipo_sala_id,inicio_utc,dia,hora,grupo,
   round(precio*(100-descuento)/100,2) AS precio,
   jsonb_agg(asiento ORDER BY posicion) AS asientos,count(*)::int AS cantidad
 FROM asientos GROUP BY id,sala_id,pelicula_id,experiencia_id,tipo_sala_id,inicio_utc,dia,hora,grupo,precio,descuento
)
INSERT INTO cine.ventas(id,numero_factura,codigo,usuario_id,operador_id,funcion_id,solicitud,total,cantidad,metodo_pago,fecha_utc,verificada_utc,snapshot_json)
SELECT md5('historial:'||c.id||':'||c.grupo)::uuid,'F-HIST-'||upper(substr(md5(c.id||':'||c.grupo),1,16)),upper(substr(md5('validacion:'||c.id||':'||c.grupo),1,12)),
 u.id,NULL,c.id,'historial:'||c.id||':'||c.grupo,c.precio*c.cantidad,c.cantidad,
 CASE WHEN (c.dia+c.grupo)%2=0 THEN 'Pago QR' ELSE 'Tarjeta de débito' END,
 c.inicio_utc-make_interval(mins=>30+((c.dia*13+c.sala_id*7+c.grupo*11)%120)::int),c.inicio_utc-interval '15 minutes',
 jsonb_build_object('peliculaId',c.pelicula_id,'pelicula',p.titulo,'numeroSala',c.sala_id,'tipoSala',c.tipo_sala_id,'tipoExperiencia',c.experiencia_id,
 'horario',to_char(c.inicio_utc AT TIME ZONE 'America/La_Paz','HH24:MI'),'fechaFuncion',to_char(c.inicio_utc AT TIME ZONE 'America/La_Paz','YYYY-MM-DD"T"HH24:MI:SS'),
 'ticketsMayores',c.cantidad,'ticketsMenores',0,'asientos',c.asientos,'cliente',u.nombre||' '||u.apellido,'documentoCliente',u.ci,'emailUsuario',u.email,
 'esPagoSimulado',true,'asientosMayoresPorCategoria',jsonb_build_object('0',c.cantidad),'preciosMayoresPorCategoria',jsonb_build_object('0',c.precio))
FROM compras c JOIN cine.peliculas p ON p.id=c.pelicula_id JOIN clientes u ON u.posicion=(c.dia+c.sala_id+c.hora+c.grupo)%u.cantidad_clientes;
INSERT INTO cine.butacas_vendidas(funcion_id,asiento,venta_id)
 SELECT v.funcion_id,a,v.id FROM cine.ventas v CROSS JOIN LATERAL jsonb_array_elements_text(v.snapshot_json->'asientos') a WHERE v.solicitud LIKE 'historial:%';

-- El cliente principal tiene una compra terminada por cada película de cartelera.
WITH ultimas AS (
 SELECT DISTINCT ON(f.pelicula_id) f.*,s.precio,s.descuento,s.tipo_sala_id,d.plano_json
 FROM cine.funciones f JOIN cine.salas s ON s.id=f.sala_id JOIN cine.disenos d ON d.id=s.diseno_id
 WHERE NOT f.preventa AND (f.inicio_utc AT TIME ZONE 'America/La_Paz')::date=(CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date-1
 AND (f.inicio_utc AT TIME ZONE 'America/La_Paz')::time='10:00'
 ORDER BY f.pelicula_id,f.sala_id
), compras AS (
 SELECT f.*,a.asientos FROM ultimas f CROSS JOIN LATERAL (
  SELECT jsonb_agg(asiento ORDER BY posicion) asientos FROM (
   SELECT asiento,posicion FROM jsonb_array_elements_text(f.plano_json->'asientos') WITH ORDINALITY a(asiento,posicion)
   WHERE NOT EXISTS(SELECT 1 FROM cine.butacas_vendidas b WHERE b.funcion_id=f.id AND b.asiento=a.asiento)
   ORDER BY posicion LIMIT 2
  ) libres
 ) a
)
INSERT INTO cine.ventas(id,numero_factura,codigo,usuario_id,operador_id,funcion_id,solicitud,total,cantidad,metodo_pago,fecha_utc,verificada_utc,snapshot_json)
SELECT md5('cliente-pelicula:'||c.id)::uuid,'F-CLIENTE-'||upper(substr(md5(c.id::text),1,16)),upper(substr(md5('cliente-validacion:'||c.id),1,12)),
 u.id,NULL,c.id,'cliente-pelicula:'||c.id,round(c.precio*(100-c.descuento)/100,2)*2,2,'Pago QR',c.inicio_utc-interval '2 hours',c.inicio_utc-interval '15 minutes',
 jsonb_build_object('peliculaId',c.pelicula_id,'pelicula',p.titulo,'numeroSala',c.sala_id,'tipoSala',c.tipo_sala_id,'tipoExperiencia',c.experiencia_id,
 'horario','10:00','fechaFuncion',to_char(c.inicio_utc AT TIME ZONE 'America/La_Paz','YYYY-MM-DD"T"HH24:MI:SS'),
 'ticketsMayores',2,'ticketsMenores',0,'asientos',c.asientos,'cliente',u.nombre||' '||u.apellido,'documentoCliente',u.ci,'emailUsuario',u.email,
 'esPagoSimulado',true,'asientosMayoresPorCategoria',jsonb_build_object('0',2),'preciosMayoresPorCategoria',jsonb_build_object('0',round(c.precio*(100-c.descuento)/100,2)))
FROM compras c JOIN cine.peliculas p ON p.id=c.pelicula_id CROSS JOIN(SELECT * FROM cine.usuarios WHERE email='cliente@cliente.com') u;
INSERT INTO cine.butacas_vendidas(funcion_id,asiento,venta_id)
 SELECT v.funcion_id,a,v.id FROM cine.ventas v CROSS JOIN LATERAL jsonb_array_elements_text(v.snapshot_json->'asientos') a WHERE v.solicitud LIKE 'cliente-pelicula:%';

-- Ocupación de hoy y próximas funciones: completas, parciales y libres en todos los horarios.
-- Tres primeras fechas de cada película/sala, siempre relativas al BAT.
-- La mezcla rota por sala, día y turno; ningún horario queda artificialmente vacío.
-- Compras de hasta cuatro entradas repartidas entre los clientes de prueba.
-- Sus pagos se distribuyen durante treinta días, siempre antes de la función y nunca en el futuro.
WITH fechas AS (
 SELECT f.*,s.precio,s.descuento,s.tipo_sala_id,d.plano_json,
   dense_rank() OVER(PARTITION BY f.sala_id,f.pelicula_id ORDER BY (f.inicio_utc AT TIME ZONE 'America/La_Paz')::date) AS dia,
   row_number() OVER(PARTITION BY f.sala_id,(f.inicio_utc AT TIME ZONE 'America/La_Paz')::date ORDER BY f.inicio_utc,f.id) AS turno
 FROM cine.funciones f JOIN cine.salas s ON s.id=f.sala_id JOIN cine.disenos d ON d.id=s.diseno_id
 WHERE (f.inicio_utc AT TIME ZONE 'America/La_Paz')::date >= (CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date
), objetivos AS (
  SELECT f.*,CASE (f.sala_id*3+f.dia+f.turno)%8
    WHEN 0 THEN jsonb_array_length(f.plano_json->'asientos')
    WHEN 1 THEN 0
    ELSE greatest(1,jsonb_array_length(f.plano_json->'asientos')*(25+((f.sala_id*7+f.dia*11+f.turno*17)%51)::int)/100)
  END AS objetivo
  FROM fechas f WHERE f.dia<=3
), clientes AS (
 SELECT u.*,row_number() OVER(ORDER BY u.id)-1 AS posicion,count(*) OVER() AS cantidad_clientes
 FROM cine.usuarios u WHERE u.activo AND u.email <> 'cliente@cliente.com'
  AND u.fecha_registro_utc <= (((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date-30)::timestamp AT TIME ZONE 'America/La_Paz')
 AND EXISTS(SELECT 1 FROM cine.usuarios_roles ur JOIN cine.roles r ON r.id=ur.role_id WHERE ur.user_id=u.id AND r.name='Cliente')
), asientos AS (
 SELECT f.*,a.asiento,a.posicion,
   (a.posicion-1)/4 AS grupo
  FROM objetivos f CROSS JOIN LATERAL (
   SELECT asiento,row_number() OVER(ORDER BY regexp_replace(asiento,'[0-9]','','g'),substring(asiento from '[0-9]+')::int) AS posicion
   FROM jsonb_array_elements_text(f.plano_json->'asientos') a(asiento)
 ) a
  WHERE a.posicion <= f.objetivo
   AND NOT EXISTS(SELECT 1 FROM cine.butacas_vendidas b WHERE b.funcion_id=f.id AND b.asiento=a.asiento)
), compras AS (
  SELECT id,sala_id,pelicula_id,experiencia_id,tipo_sala_id,inicio_utc,dia,grupo,
   round(precio*(100-descuento)/100,2) AS precio,
   jsonb_agg(asiento ORDER BY posicion) AS asientos,count(*)::int AS cantidad
  FROM asientos GROUP BY id,sala_id,pelicula_id,experiencia_id,tipo_sala_id,inicio_utc,dia,grupo,precio,descuento
)
INSERT INTO cine.ventas(id,numero_factura,codigo,usuario_id,operador_id,funcion_id,solicitud,total,cantidad,metodo_pago,fecha_utc,snapshot_json)
SELECT md5('ocupacion:'||c.id||':'||c.grupo)::uuid,'F-OCUP-'||upper(substr(md5(c.id||':'||c.grupo),1,16)),
 upper(substr(md5('ingreso:'||c.id||':'||c.grupo),1,12)),u.id,NULL,c.id,'ocupacion:'||c.id||':'||c.grupo,c.precio*c.cantidad,c.cantidad,
 CASE WHEN c.grupo%2=0 THEN 'Pago QR' ELSE 'Tarjeta de débito' END,
 least(CURRENT_TIMESTAMP,c.inicio_utc-interval '1 hour',
   (((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date-((c.sala_id*7+c.grupo*11+c.pelicula_id+c.dia*5)%30)::int)::timestamp
     +make_interval(hours=>8+((c.sala_id+c.grupo)%14)::int,mins=>((c.grupo*17+c.sala_id)%60)::int)) AT TIME ZONE 'America/La_Paz'),
 jsonb_build_object('solicitud','ocupacion:'||c.id||':'||c.grupo,'peliculaId',p.id,'pelicula',p.titulo,'numeroSala',c.sala_id,
 'tipoSala',c.tipo_sala_id,'tipoExperiencia',c.experiencia_id,'horario',to_char(c.inicio_utc AT TIME ZONE 'America/La_Paz','HH24:MI'),
 'ticketsMayores',c.cantidad,'ticketsMenores',0,'asientos',c.asientos,'cliente',u.nombre||' '||u.apellido,
 'documentoCliente',u.ci,'emailUsuario',u.email,'asientosMayoresPorCategoria',jsonb_build_object('0',c.cantidad),
 'preciosMayoresPorCategoria',jsonb_build_object('0',c.precio))
FROM compras c JOIN cine.peliculas p ON p.id=c.pelicula_id
JOIN clientes u ON u.posicion=(c.sala_id+c.grupo)%u.cantidad_clientes;

INSERT INTO cine.butacas_vendidas(funcion_id,asiento,venta_id)
 SELECT v.funcion_id,a,v.id FROM cine.ventas v CROSS JOIN LATERAL jsonb_array_elements_text(v.snapshot_json->'asientos') a
 WHERE v.solicitud LIKE 'ocupacion:%';

-- Los snapshots históricos corresponden a las mismas películas, salas y butacas.
UPDATE cine.ventas v SET snapshot_json=v.snapshot_json || jsonb_build_object(
 'peliculaId',p.id,'pelicula',p.titulo,'fechaFuncion',to_char(f.inicio_utc AT TIME ZONE 'America/La_Paz','YYYY-MM-DD"T"HH24:MI:SS'),
 'generos',coalesce((SELECT jsonb_agg(g.nombre ORDER BY g.nombre) FROM cine.peliculas_generos pg JOIN cine.generos g ON g.id=pg.genero_id WHERE pg.pelicula_id=p.id),'[]'),
 'asientos',(SELECT jsonb_agg(b.asiento ORDER BY b.asiento) FROM cine.butacas_vendidas b WHERE b.venta_id=v.id),
 'tipoSala',s.tipo_sala_id,'tipoSalaNombre',ts.nombre,'experienciaNombre',e.nombre)
 FROM cine.funciones f JOIN cine.peliculas p ON p.id=f.pelicula_id JOIN cine.salas s ON s.id=f.sala_id JOIN cine.tipos_sala ts ON ts.id=s.tipo_sala_id JOIN cine.experiencias e ON e.id=f.experiencia_id WHERE f.id=v.funcion_id;

-- Confitería ligada a las visitas del histórico: dos de cada tres compras llevan un combo.
-- Varían los clientes, productos y cantidades; pago y retiro preceden a la función.
WITH compras AS (
 SELECT v.*,f.sala_id,f.inicio_utc,row_number() OVER(ORDER BY f.inicio_utc,v.id) AS posicion
 FROM cine.ventas v JOIN cine.funciones f ON f.id=v.funcion_id WHERE v.solicitud LIKE 'historial:%'
), combos AS (
 SELECT c.*,row_number() OVER(ORDER BY c.id)-1 AS posicion,count(*) OVER() AS cantidad_combos
 FROM cine.combos c WHERE c.publicado
)
INSERT INTO cine.pedidos (id,numero,token,solicitud,codigo,usuario_id,propietario_invitado,nombre_retiro,estado,metodo_pago,total,creado_utc,retirado_utc,entregado_por_id,pagado_utc)
SELECT md5('seed-pedido:'||v.id)::uuid,'P-SEED-'||upper(substr(md5(v.id::text),1,16)),md5('token:'||v.id)||substr(md5(c.id::text),1,16),'seed-pedido:'||v.id||':'||c.id,
 'CF-SEED-'||upper(substr(md5(v.id::text),1,16)),u.id,'',u.nombre||' '||u.apellido,'Retirado',CASE WHEN v.posicion%2=0 THEN 'QR' ELSE 'Tarjeta' END,
 c.precio*least(v.cantidad,2+((v.posicion+v.sala_id)%3)::int),
 v.inicio_utc-interval '55 minutes',v.inicio_utc-interval '30 minutes',w.usuario_id,v.inicio_utc-interval '45 minutes'
FROM compras v JOIN combos c ON c.posicion=(v.posicion+v.sala_id)%c.cantidad_combos
JOIN cine.usuarios u ON u.id=v.usuario_id
CROSS JOIN (SELECT t.usuario_id FROM cine.trabajadores t JOIN cine.usuarios u ON u.id=t.usuario_id
 WHERE u.fecha_registro_utc <= (((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date-30)::timestamp AT TIME ZONE 'America/La_Paz')
 ORDER BY u.fecha_registro_utc,t.id LIMIT 1) w WHERE v.posicion%3<>0;
INSERT INTO cine.pedido_lineas(id,pedido_id,combo_id,nombre,categoria,cantidad,precio_unitario)
SELECT (SELECT coalesce(max(id),0) FROM cine.pedido_lineas)+row_number() OVER(ORDER BY p.id,c.id),p.id,c.id,c.nombre,cat.nombre,(p.total/c.precio)::int,c.precio
FROM cine.pedidos p JOIN cine.combos c ON c.id=split_part(p.solicitud,':',3)::int JOIN cine.categorias cat ON cat.id=c.categoria_id WHERE p.solicitud LIKE 'seed-pedido:%';

-- Reseñas de otros clientes: únicamente funciones compradas y terminadas.
INSERT INTO cine.resenas(id,funcion_id,pelicula_id,usuario_id,destacada,puntuacion,comentario,fecha_utc)
SELECT md5('resena-historial:'||v.id)::uuid,f.id,p.id,v.usuario_id,(sala_id%5=0),3+(sala_id%3),
 'Vi '||p.titulo||'. '||CASE
 WHEN EXISTS(SELECT 1 FROM cine.peliculas_generos g WHERE g.pelicula_id=p.id AND g.genero_id=11) THEN 'La tensión y el sonido se disfrutan mucho en el cine. Una función intensa y una sala muy cómoda.'
 WHEN EXISTS(SELECT 1 FROM cine.peliculas_generos g WHERE g.pelicula_id=p.id AND g.genero_id=12) THEN 'La música y las interpretaciones hicieron que la experiencia valiera la pena.'
 ELSE 'Me gustaron las actuaciones y la fotografía. La imagen y el sonido de la sala acompañaron muy bien la historia.' END,
 least(CURRENT_TIMESTAMP,f.inicio_utc+make_interval(mins=>f.duracion)+interval '10 minutes')
FROM cine.ventas v JOIN cine.funciones f ON f.id=v.funcion_id JOIN cine.peliculas p ON p.id=f.pelicula_id
WHERE v.solicitud LIKE 'historial:%' AND f.inicio_utc+make_interval(mins=>f.duracion)<=CURRENT_TIMESTAMP AND f.sala_id%3=0;

-- Cliente de demostración: exactamente dos funciones terminadas por calificar.
-- Las compras futuras o en curso nunca generan reseñas ni aparecen como calificadas.
WITH pendientes AS (SELECT id FROM (
 SELECT DISTINCT ON(f.pelicula_id) f.id,f.inicio_utc+make_interval(mins=>f.duracion) AS fin
 FROM cine.funciones f WHERE f.inicio_utc+make_interval(mins=>f.duracion)<=CURRENT_TIMESTAMP
 AND EXISTS(SELECT 1 FROM cine.ventas v WHERE v.funcion_id=f.id AND v.usuario_id=(SELECT id FROM cine.usuarios WHERE email='cliente@cliente.com'))
 ORDER BY f.pelicula_id,fin DESC,f.id
) ultimas ORDER BY fin DESC,id LIMIT 2), historial AS (
 SELECT f.*,row_number() OVER(ORDER BY f.inicio_utc DESC,f.id) AS posicion
 FROM cine.funciones f WHERE f.inicio_utc+make_interval(mins=>f.duracion)<=CURRENT_TIMESTAMP
 AND EXISTS(SELECT 1 FROM cine.ventas v WHERE v.funcion_id=f.id AND v.usuario_id=(SELECT id FROM cine.usuarios WHERE email='cliente@cliente.com'))
 AND f.id NOT IN(SELECT id FROM pendientes)
)
INSERT INTO cine.resenas(id,funcion_id,pelicula_id,usuario_id,destacada,puntuacion,comentario,fecha_utc)
 SELECT md5('resena-cliente:'||f.id)::uuid,f.id,f.pelicula_id,u.id,false,2+(f.posicion%4)::int,
 (ARRAY['La historia y el sonido hicieron que disfrutara mucho la función.',
 'Una buena experiencia para compartir en el cine. Me gustaron especialmente las actuaciones y el ritmo de la película.',
 'La fotografía tiene escenas que se disfrutan mucho más en pantalla grande. La historia se toma su tiempo para presentar a los personajes y luego consigue mantener el interés hasta el final. También me gustó el trabajo de sonido: acompaña los momentos más tranquilos sin distraer y da fuerza a las escenas de acción. Salí con ganas de conversar sobre el desenlace y algunos detalles que seguramente descubriría en una segunda visita.',
 'Disfruté la película y la comodidad de la sala.'])[1+(f.posicion%4)::int],
 least(CURRENT_TIMESTAMP,f.inicio_utc+make_interval(mins=>f.duracion)+interval '5 minutes')
 FROM historial f CROSS JOIN(SELECT id FROM cine.usuarios WHERE email='cliente@cliente.com') u
 WHERE NOT EXISTS(SELECT 1 FROM cine.resenas r WHERE r.usuario_id=u.id AND r.funcion_id=f.id);
WITH pendientes AS (SELECT id FROM (
 SELECT DISTINCT ON(f.pelicula_id) f.id,f.inicio_utc+make_interval(mins=>f.duracion) AS fin
 FROM cine.funciones f WHERE f.inicio_utc+make_interval(mins=>f.duracion)<=CURRENT_TIMESTAMP
 AND EXISTS(SELECT 1 FROM cine.ventas v WHERE v.funcion_id=f.id AND v.usuario_id=(SELECT id FROM cine.usuarios WHERE email='cliente@cliente.com'))
 ORDER BY f.pelicula_id,fin DESC,f.id
) ultimas ORDER BY fin DESC,id LIMIT 2)
DELETE FROM cine.resenas r WHERE r.usuario_id=(SELECT id FROM cine.usuarios WHERE email='cliente@cliente.com') AND r.funcion_id IN(SELECT id FROM pendientes);

-- Reajustar secuencias despues de los IDs explicitos del seed.
DO $$ DECLARE tabla text; secuencia text; siguiente bigint; BEGIN
 FOREACH tabla IN ARRAY ARRAY['categorias','combos','disenos','distribuidoras','experiencias','generos','peliculas','salas','tipos_sala','trabajadores','banners','estrenos','pedido_lineas'] LOOP
  secuencia := pg_get_serial_sequence('cine.'||tabla,'id');
  EXECUTE format('SELECT coalesce(max(id),0)+1 FROM cine.%I',tabla) INTO siguiente;
  PERFORM setval(secuencia,siguiente,false);
 END LOOP;
END $$;
-- La API del servidor es el unico acceso a los datos de negocio.
REVOKE ALL ON SCHEMA cine FROM PUBLIC;
DO $$ DECLARE rol text; BEGIN
 FOREACH rol IN ARRAY ARRAY['anon','authenticated'] LOOP
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=rol) THEN
   EXECUTE format('REVOKE ALL ON SCHEMA cine FROM %I',rol);
   EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA cine FROM %I',rol);
   EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA cine FROM %I',rol);
  END IF;
 END LOOP;
END $$;
COMMIT;
